{
  "application": "ppt-generation",
  "case_id": "case-nasa-co2",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 9,
    "audience": "policy analysts and climate negotiators reviewing global CO2 emission trends and national responsibilities",
    "tone": "data-forward, analytical, authoritative"
  },
  "brief": {
    "title": "Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities",
    "one_liner": "A data-driven overview of how global carbon dioxide emissions have evolved from the Industrial Revolution to 2024, highlighting regional shifts, per capita disparities, and the latest annual changes.",
    "goal": "Equip the audience with a clear understanding of who emits the most CO₂ (total and per capita), how the geographic distribution of emissions has shifted over time, and what the 2024 annual change data reveals about current trajectories."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities",
      "objective": "Cover slide with deck title, subtitle summarizing scope (1750–2024), data source attribution (Global Carbon Budget 2025, NASA), and a striking visual element."
    },
    {
      "id": "atmospheric-co2-milestone",
      "title": "Atmospheric CO₂ Reaches 429 ppm — 50% Above Pre-Industrial Levels",
      "objective": "Present the latest Mauna Loa measurement (429 ppm, Feb 2026) and contextualize it against the pre-industrial baseline of ~280 ppm. Use a simple callout stat with a timeline annotation showing the acceleration since 1958."
    },
    {
      "id": "global-emissions-six-fold-since-1950",
      "title": "Global Fossil Fuel CO₂ Emissions Grew Six-Fold: 6 Billion to 35+ Billion Tonnes",
      "objective": "Show the trajectory of total global CO₂ emissions from 1750 to 2024 using a line chart description. Highlight key inflection points: 6 Bt in 1950, 20 Bt by 1990, and 35+ Bt today. Reference figure_2.jpg."
    },
    {
      "id": "china-surpasses-us-total-emissions",
      "title": "China Now Emits Over 12 Billion Tonnes — More Than Double the United States",
      "objective": "Compare annual total CO₂ emissions of the top emitters (China, US, India, Germany, UK, Brazil, France) using the data table and reference figure_3.jpg. Emphasize China's steep rise post-2000 and the US decline from its ~6 Bt peak."
    },
    {
      "id": "regional-share-shift",
      "title": "Asia Now Accounts for ~50% of Global Emissions; US + Europe Below One-Third",
      "objective": "Illustrate the dramatic shift in regional emission shares from 1900 (Europe + US > 90%) to 2024 (Asia ~50%, US + Europe < 33%). Use a stacked area or comparison visual description. Mention Africa and South America each at 3–4%."
    },
    {
      "id": "per-capita-150x-gap",
      "title": "Per Capita Gap: 15 t in the US vs. 0.1 t in Chad — a 150× Disparity",
      "objective": "Present per capita CO₂ emissions for selected countries using a horizontal bar chart description. Highlight the US (~15 t), Canada (~13 t), China (~9 t), EU-27 (~7 t), World average (~5 t), India (~2 t), UK (~4 t), Kenya (<1 t). Reference figure_1.jpg for the per capita line chart."
    },
    {
      "id": "annual-change-2024-map",
      "title": "2024 Snapshot: US and Europe Cut Emissions While Russia and SE Asia Increase",
      "objective": "Describe the 2024 annual percentage change map (figure_4.jpg). Highlight that the US and much of Europe show blue (negative change, -1% to -5%), while Russia, parts of Africa, and Southeast Asia show orange/red (positive change, +2% to +10%). Note specific regional patterns."
    },
    {
      "id": "energy-mix-drives-differences",
      "title": "Energy Mix Explains Why France Emits Far Less Per Capita Than Germany",
      "objective": "Explain that countries with similar living standards can have very different per capita emissions depending on energy sources. Contrast France/UK (high nuclear and renewables, lower per capita CO₂) with Germany/Netherlands (higher fossil fuel share). Use a small comparison table."
    },
    {
      "id": "key-takeaways",
      "title": "Key Takeaways: Emissions Are Still Rising, But the Map of Responsibility Is Shifting",
      "objective": "Summarize 4–5 key findings as bullet points: (1) Global emissions exceed 35 Bt and have not yet peaked; (2) China alone emits >25% of global total; (3) Per capita inequalities remain extreme (150×); (4) US and Europe are declining but historical cumulative responsibility remains large; (5) Policy and energy mix choices — not just prosperity — determine per capita outcomes."
    }
  ]
}

