    <style>
        /* ==========================================
           CSS CUSTOM PROPERTIES — THEME
           Deep slate + teal accent — authoritative climate data aesthetic
           ========================================== */
        :root {
            --bg-primary: #0b1220;
            --bg-secondary: #0f1a2e;
            --bg-card: #131f35;
            --bg-card-hover: #1a2845;
            --border: rgba(255, 255, 255, 0.08);
            --border-strong: rgba(255, 255, 255, 0.15);

            --text-primary: #e8edf5;
            --text-secondary: #8a9ab8;
            --text-muted: #556078;

            --accent: #00c9a7;
            --accent-glow: rgba(0, 201, 167, 0.25);
            --accent-dim: rgba(0, 201, 167, 0.1);
            --accent-blue: #3b82f6;
            --accent-orange: #f97316;
            --accent-red: #ef4444;
            --accent-yellow: #eab308;

            --font-display: 'Syne', sans-serif;
            --font-body: 'Manrope', sans-serif;
            --font-mono: 'JetBrains Mono', monospace;

            /* Typography — clamp() for responsive scaling */
            --title-size: clamp(1.5rem, 5vw, 4rem);
            --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);
            --h3-size: clamp(1rem, 2.5vw, 1.75rem);
            --body-size: clamp(0.75rem, 1.5vw, 1.05rem);
            --small-size: clamp(0.65rem, 1vw, 0.875rem);
            --mono-size: clamp(0.7rem, 1.2vw, 0.95rem);

            /* Spacing */
            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.5rem, 2vw, 1.5rem);
            --element-gap: clamp(0.25rem, 1vw, 0.75rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.65s;
        }

        /* ==========================================
           RESET
           ========================================== */
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        /* ==========================================
           VIEWPORT BASE CSS (mandatory)
           ========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }

        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }

        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }

        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ==========================================
           BASE BODY / FONT
           ========================================== */
        body {
            font-family: var(--font-body);
            color: var(--text-primary);
            background: var(--bg-primary);
        }

        /* ==========================================
           REVEAL ANIMATIONS
           Triggered when .visible added by IntersectionObserver
           ========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(24px);
            transition:
                opacity var(--duration-normal) var(--ease-out-expo),
                transform var(--duration-normal) var(--ease-out-expo);
        }

        .slide.visible .reveal { opacity: 1; transform: translateY(0); }

        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.15s; }
        .reveal:nth-child(3) { transition-delay: 0.25s; }
        .reveal:nth-child(4) { transition-delay: 0.35s; }
        .reveal:nth-child(5) { transition-delay: 0.45s; }
        .reveal:nth-child(6) { transition-delay: 0.55s; }

        .reveal-left {
            opacity: 0;
            transform: translateX(calc(-1 * clamp(20px, 4vw, 50px)));
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal-left { opacity: 1; transform: translateX(0); }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.92);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal-scale { opacity: 1; transform: scale(1); }

        /* ==========================================
           PROGRESS BAR
           ========================================== */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent), var(--accent-blue));
            width: 0%;
            z-index: 1000;
            transition: width 0.3s ease;
        }

        /* ==========================================
           NAV DOTS
           ========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.75rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(6px, 1vh, 10px);
            z-index: 100;
        }

        .nav-dot {
            width: clamp(6px, 1vw, 9px);
            height: clamp(6px, 1vw, 9px);
            border-radius: 50%;
            background: var(--text-muted);
            cursor: pointer;
            transition: all 0.3s ease;
            border: none;
        }

        .nav-dot.active {
            background: var(--accent);
            transform: scale(1.4);
            box-shadow: 0 0 8px var(--accent-glow);
        }

        /* ==========================================
           SHARED SLIDE BACKGROUND
           ========================================== */
        .slide {
            background: var(--bg-primary);
        }

        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background:
                radial-gradient(ellipse at 0% 0%, rgba(0, 201, 167, 0.06) 0%, transparent 50%),
                radial-gradient(ellipse at 100% 100%, rgba(59, 130, 246, 0.05) 0%, transparent 50%);
            pointer-events: none;
        }

        /* Grid lines for data-forward feel */
        .slide::after {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(255,255,255,0.018) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.018) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
        }

        /* ==========================================
           SLIDE HEADER (shared chrome)
           ========================================== */
        .slide-header {
            position: absolute;
            top: clamp(0.75rem, 2vh, 1.5rem);
            left: var(--slide-padding);
            right: var(--slide-padding);
            display: flex;
            align-items: center;
            justify-content: space-between;
            z-index: 10;
        }

        .slide-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent);
            letter-spacing: 0.12em;
            text-transform: uppercase;
        }

        .slide-num {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
        }

        /* ==========================================
           SLIDE 1: TITLE
           ========================================== */
        .slide-title {
            background: var(--bg-primary);
        }

        .title-inner {
            display: flex;
            flex-direction: column;
            justify-content: center;
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2rem);
            position: relative;
            z-index: 2;
        }

        .title-eyebrow {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--accent);
            letter-spacing: 0.18em;
            text-transform: uppercase;
            margin-bottom: clamp(0.5rem, 1.5vh, 1rem);
        }

        .title-main {
            font-family: var(--font-display);
            font-size: clamp(1.8rem, 5.5vw, 4.5rem);
            font-weight: 800;
            line-height: 1.05;
            color: var(--text-primary);
            max-width: 18ch;
            margin-bottom: clamp(0.75rem, 2vh, 1.5rem);
        }

        .title-main em {
            font-style: normal;
            color: var(--accent);
        }

        .title-subtitle {
            font-size: clamp(0.85rem, 1.8vw, 1.2rem);
            color: var(--text-secondary);
            font-weight: 400;
            max-width: 55ch;
            line-height: 1.6;
            margin-bottom: clamp(1rem, 3vh, 2.5rem);
        }

        .title-meta {
            display: flex;
            gap: clamp(1rem, 3vw, 2.5rem);
            flex-wrap: wrap;
        }

        .meta-item {
            display: flex;
            flex-direction: column;
            gap: 3px;
        }

        .meta-label {
            font-family: var(--font-mono);
            font-size: clamp(0.6rem, 0.9vw, 0.75rem);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        .meta-value {
            font-size: clamp(0.75rem, 1.2vw, 0.95rem);
            color: var(--text-secondary);
            font-weight: 500;
        }

        /* Large decorative number in bg */
        .title-bg-num {
            position: absolute;
            right: calc(-1 * clamp(0.5rem, 2vw, 2rem));
            bottom: calc(-1 * clamp(1rem, 4vh, 4rem));
            font-family: var(--font-display);
            font-size: clamp(10rem, 30vw, 28rem);
            font-weight: 800;
            color: rgba(0, 201, 167, 0.04);
            line-height: 1;
            pointer-events: none;
            user-select: none;
            z-index: 1;
        }

        /* Accent bar on left */
        .title-accent-bar {
            position: absolute;
            left: 0;
            top: 15%;
            bottom: 15%;
            width: 4px;
            background: linear-gradient(180deg, var(--accent) 0%, var(--accent-blue) 100%);
            border-radius: 0 2px 2px 0;
        }

        /* ==========================================
           SLIDE 2: ATMOSPHERIC CO₂ MILESTONE
           ========================================== */
        .milestone-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1.5rem, 4vw, 4rem);
            align-items: center;
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2.5rem);
            position: relative;
            z-index: 2;
        }

        .big-stat {
            display: flex;
            flex-direction: column;
            gap: clamp(0.25rem, 1vh, 0.75rem);
        }

        .stat-number {
            font-family: var(--font-display);
            font-size: clamp(3.5rem, 10vw, 9rem);
            font-weight: 800;
            line-height: 0.9;
            color: var(--accent);
            text-shadow: 0 0 80px var(--accent-glow);
        }

        .stat-unit {
            font-family: var(--font-mono);
            font-size: clamp(0.9rem, 2vw, 1.5rem);
            color: var(--text-secondary);
            letter-spacing: 0.05em;
        }

        .stat-caption {
            font-size: var(--body-size);
            color: var(--text-secondary);
            max-width: 30ch;
            line-height: 1.5;
            margin-top: clamp(0.25rem, 1vh, 0.5rem);
        }

        .milestone-context {
            display: flex;
            flex-direction: column;
            gap: clamp(0.75rem, 2vh, 1.5rem);
        }

        .context-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.75rem, 2vw, 1.25rem);
        }

        .context-card-label {
            font-family: var(--font-mono);
            font-size: clamp(0.6rem, 0.9vw, 0.75rem);
            color: var(--accent);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-bottom: 0.4em;
        }

        .context-card-val {
            font-size: clamp(0.85rem, 1.6vw, 1.1rem);
            font-weight: 600;
            color: var(--text-primary);
        }

        .context-card-sub {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.25em;
            line-height: 1.4;
        }

        /* Comparison bar visual */
        .ppm-bar-wrap {
            margin-top: clamp(0.5rem, 1.5vh, 1rem);
        }

        .ppm-bar-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.5vw, 1rem);
            margin-bottom: 0.6rem;
        }

        .ppm-bar-label {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-secondary);
            min-width: clamp(6rem, 10vw, 9rem);
        }

        .ppm-bar-track {
            flex: 1;
            height: clamp(6px, 1vh, 10px);
            background: rgba(255,255,255,0.07);
            border-radius: 99px;
            overflow: hidden;
        }

        .ppm-bar-fill {
            height: 100%;
            border-radius: 99px;
            transition: width 1.2s var(--ease-out-expo);
        }

        .slide.visible .ppm-bar-fill { /* width set inline via data attrs */ }

        .ppm-bar-fill.pre-industrial { background: var(--text-muted); width: 0; }
        .ppm-bar-fill.current { background: linear-gradient(90deg, var(--accent-blue), var(--accent)); width: 0; }

        .slide.visible .ppm-bar-fill.pre-industrial { width: 65%; transition-delay: 0.4s; }
        .slide.visible .ppm-bar-fill.current { width: 100%; transition-delay: 0.6s; }

        .ppm-bar-num {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-secondary);
            min-width: 3.5rem;
            text-align: right;
        }

        /* ==========================================
           SLIDE 3: GLOBAL EMISSIONS TRAJECTORY
           ========================================== */
        .trajectory-layout {
            display: grid;
            grid-template-rows: auto 1fr;
            gap: clamp(0.75rem, 2vh, 1.5rem);
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2.5rem);
            position: relative;
            z-index: 2;
        }

        .trajectory-header h2 {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 800;
            color: var(--text-primary);
            line-height: 1.15;
        }

        .trajectory-header .subtitle {
            font-size: var(--body-size);
            color: var(--text-secondary);
            margin-top: 0.4em;
        }

        .trajectory-body {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 3vw, 2.5rem);
            overflow: hidden;
        }

        /* SVG line chart for emissions trajectory */
        .chart-container {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.75rem, 2vw, 1.25rem);
            overflow: hidden;
            display: flex;
            flex-direction: column;
        }

        .chart-title {
            font-family: var(--font-mono);
            font-size: clamp(0.6rem, 0.9vw, 0.75rem);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-bottom: 0.5rem;
        }

        .chart-svg-wrap {
            flex: 1;
            overflow: hidden;
        }

        .chart-svg-wrap svg {
            width: 100%;
            height: 100%;
            max-height: min(28vh, 240px);
        }

        .trajectory-milestones {
            display: flex;
            flex-direction: column;
            justify-content: center;
            gap: clamp(0.5rem, 1.5vh, 1rem);
        }

        .milestone-row {
            display: flex;
            align-items: center;
            gap: clamp(0.75rem, 2vw, 1.25rem);
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.5vw, 1rem);
        }

        .milestone-year {
            font-family: var(--font-mono);
            font-size: clamp(0.75rem, 1.2vw, 0.95rem);
            color: var(--accent);
            font-weight: 600;
            min-width: 3.5rem;
        }

        .milestone-val {
            font-family: var(--font-display);
            font-size: clamp(1.1rem, 2.5vw, 1.8rem);
            font-weight: 800;
            color: var(--text-primary);
        }

        .milestone-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.3;
        }

        /* ==========================================
           SLIDE 4: TOP EMITTERS
           ========================================== */
        .emitters-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 3vw, 2.5rem);
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2.5rem);
            position: relative;
            z-index: 2;
            align-items: start;
        }

        .emitters-left {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
        }

        .section-heading {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 800;
            color: var(--text-primary);
            line-height: 1.15;
        }

        .section-subheading {
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        /* Horizontal bar chart */
        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.35rem, 1vh, 0.65rem);
        }

        .bar-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.5vw, 0.875rem);
        }

        .bar-country {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-secondary);
            min-width: clamp(4.5rem, 8vw, 7rem);
            text-align: right;
        }

        .bar-track {
            flex: 1;
            height: clamp(10px, 1.8vh, 18px);
            background: rgba(255,255,255,0.05);
            border-radius: 3px;
            overflow: hidden;
        }

        .bar-fill {
            height: 100%;
            border-radius: 3px;
            width: 0;
            transition: width 1s var(--ease-out-expo);
        }

        .slide.visible .bar-fill { /* Widths applied via inline style */ }

        .bar-fill.china   { background: linear-gradient(90deg, #f97316, #ef4444); }
        .bar-fill.usa     { background: linear-gradient(90deg, #3b82f6, #6366f1); }
        .bar-fill.india   { background: linear-gradient(90deg, #eab308, #f97316); }
        .bar-fill.eu      { background: linear-gradient(90deg, var(--accent), var(--accent-blue)); }
        .bar-fill.germany { background: rgba(139, 154, 184, 0.5); }
        .bar-fill.brazil  { background: rgba(139, 154, 184, 0.4); }
        .bar-fill.uk      { background: rgba(139, 154, 184, 0.35); }
        .bar-fill.france  { background: rgba(139, 154, 184, 0.3); }

        .bar-val {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
            min-width: 4rem;
        }

        .emitters-right {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
            justify-content: center;
        }

        .figure-wrap {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            overflow: hidden;
            flex-shrink: 0;
        }

        .figure-wrap img {
            width: 100%;
            height: auto;
            max-height: min(40vh, 320px);
            object-fit: cover;
            display: block;
        }

        .figure-caption {
            font-family: var(--font-mono);
            font-size: clamp(0.55rem, 0.85vw, 0.72rem);
            color: var(--text-muted);
            padding: 0.4rem 0.75rem;
            border-top: 1px solid var(--border);
        }

        /* ==========================================
           SLIDE 5: REGIONAL SHARE SHIFT
           ========================================== */
        .regional-layout {
            display: grid;
            grid-template-rows: auto 1fr;
            gap: clamp(0.5rem, 1.5vh, 1.25rem);
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2.5rem);
            position: relative;
            z-index: 2;
        }

        .regional-body {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1.5rem, 4vw, 3rem);
            align-items: center;
            overflow: hidden;
        }

        .era-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.875rem, 2vw, 1.5rem);
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
        }

        .era-year {
            font-family: var(--font-display);
            font-size: clamp(1.8rem, 4vw, 3rem);
            font-weight: 800;
            color: var(--text-muted);
        }

        .era-year.current { color: var(--accent); }

        /* Stacked area visual using CSS */
        .region-stack {
            display: flex;
            flex-direction: column;
            gap: 3px;
            border-radius: 6px;
            overflow: hidden;
        }

        .region-band {
            display: flex;
            align-items: center;
            padding: clamp(4px, 1vh, 8px) clamp(0.5rem, 1.5vw, 1rem);
            gap: 0.75rem;
        }

        .region-band-label {
            font-size: var(--small-size);
            font-weight: 600;
            color: rgba(255,255,255,0.9);
            min-width: 6rem;
        }

        .region-band-pct {
            font-family: var(--font-mono);
            font-size: clamp(0.7rem, 1.2vw, 1rem);
            font-weight: 700;
            color: rgba(255,255,255,0.95);
            margin-left: auto;
        }

        .band-eu-us-1900 { background: #3b5998; }
        .band-asia-1900 { background: #1e3a5f; }
        .band-other-1900 { background: #0f2340; }

        .band-asia-2024 { background: linear-gradient(90deg, #f97316, #ef4444); }
        .band-eu-us-2024 { background: linear-gradient(90deg, #3b82f6, #6366f1); }
        .band-other-2024 { background: rgba(80, 100, 130, 0.8); }

        .shift-arrow {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 0.5rem;
        }

        .shift-arrow-icon {
            font-size: clamp(1.5rem, 3vw, 2.5rem);
            color: var(--accent);
            opacity: 0.7;
        }

        .shift-note {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: center;
            line-height: 1.4;
        }

        /* ==========================================
           SLIDE 6: PER CAPITA 150× GAP
           ========================================== */
        .percapita-layout {
            display: grid;
            grid-template-columns: 1.1fr 0.9fr;
            gap: clamp(1rem, 3vw, 2.5rem);
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2.5rem);
            position: relative;
            z-index: 2;
            align-items: start;
        }

        .percapita-chart {
            display: flex;
            flex-direction: column;
            gap: clamp(0.3rem, 0.8vh, 0.6rem);
            overflow: hidden;
        }

        .pc-bar-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 1.5vw, 0.875rem);
        }

        .pc-country {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-secondary);
            min-width: clamp(3.5rem, 6vw, 6rem);
            text-align: right;
        }

        .pc-track {
            flex: 1;
            height: clamp(8px, 1.6vh, 16px);
            background: rgba(255,255,255,0.05);
            border-radius: 3px;
            overflow: hidden;
        }

        .pc-fill {
            height: 100%;
            border-radius: 3px;
            width: 0;
            transition: width 1.1s var(--ease-out-expo);
        }

        .slide.visible .pc-fill { /* applied via inline style */ }

        .pc-fill.highest { background: linear-gradient(90deg, #ef4444, #f97316); }
        .pc-fill.high    { background: linear-gradient(90deg, #f97316, #eab308); }
        .pc-fill.medium  { background: linear-gradient(90deg, #eab308, #84cc16); }
        .pc-fill.average { background: rgba(99, 102, 241, 0.8); }
        .pc-fill.low     { background: linear-gradient(90deg, var(--accent), var(--accent-blue)); }
        .pc-fill.lowest  { background: rgba(139, 154, 184, 0.4); }

        .pc-val {
            font-family: var(--font-mono);
            font-size: var(--small-size);
            color: var(--text-muted);
            min-width: 3rem;
        }

        .percapita-right {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
            justify-content: center;
        }

        .figure-wrap-sm img {
            max-height: min(32vh, 220px);
        }

        .highlight-box {
            background: var(--accent-dim);
            border: 1px solid rgba(0, 201, 167, 0.3);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.5vw, 1rem);
        }

        .highlight-box p {
            font-size: var(--body-size);
            color: var(--text-primary);
            line-height: 1.5;
        }

        .highlight-box strong {
            color: var(--accent);
        }

        /* ==========================================
           SLIDE 7: 2024 ANNUAL CHANGE MAP
           ========================================== */
        .map-layout {
            display: grid;
            grid-template-rows: auto 1fr;
            gap: clamp(0.5rem, 1.5vh, 1.25rem);
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2.5rem);
            position: relative;
            z-index: 2;
        }

        .map-body {
            display: grid;
            grid-template-columns: 1.5fr 1fr;
            gap: clamp(1rem, 2.5vw, 2rem);
            overflow: hidden;
            align-items: start;
        }

        .map-figure {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            overflow: hidden;
        }

        .map-figure img {
            width: 100%;
            height: auto;
            max-height: min(52vh, 400px);
            object-fit: cover;
            display: block;
        }

        .map-analysis {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
        }

        .change-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.5vw, 1rem);
            border-left: 3px solid transparent;
        }

        .change-card.declining { border-left-color: var(--accent); }
        .change-card.rising { border-left-color: var(--accent-orange); }
        .change-card.large-jump { border-left-color: var(--accent-red); }

        .change-card-header {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            margin-bottom: 0.3rem;
        }

        .change-dot {
            width: clamp(8px, 1.2vw, 12px);
            height: clamp(8px, 1.2vw, 12px);
            border-radius: 50%;
            flex-shrink: 0;
        }

        .dot-blue  { background: var(--accent); }
        .dot-orange { background: var(--accent-orange); }
        .dot-red   { background: var(--accent-red); }

        .change-card-title {
            font-weight: 600;
            font-size: var(--body-size);
            color: var(--text-primary);
        }

        .change-card-body {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.45;
        }

        /* ==========================================
           SLIDE 8: ENERGY MIX
           ========================================== */
        .energy-layout {
            display: grid;
            grid-template-rows: auto 1fr;
            gap: clamp(0.5rem, 1.5vh, 1.25rem);
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2.5rem);
            position: relative;
            z-index: 2;
        }

        .energy-body {
            display: grid;
            grid-template-columns: 1.1fr 0.9fr;
            gap: clamp(1.5rem, 3.5vw, 3rem);
            overflow: hidden;
            align-items: start;
        }

        /* Comparison table */
        .compare-table {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            overflow: hidden;
        }

        .compare-table table {
            width: 100%;
            border-collapse: collapse;
        }

        .compare-table th {
            background: rgba(255,255,255,0.04);
            padding: clamp(0.4rem, 1.2vw, 0.8rem) clamp(0.5rem, 1.5vw, 1rem);
            font-family: var(--font-mono);
            font-size: clamp(0.6rem, 0.9vw, 0.75rem);
            font-weight: 600;
            color: var(--text-muted);
            text-align: left;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            border-bottom: 1px solid var(--border);
        }

        .compare-table td {
            padding: clamp(0.4rem, 1.2vw, 0.75rem) clamp(0.5rem, 1.5vw, 1rem);
            font-size: var(--small-size);
            color: var(--text-primary);
            border-bottom: 1px solid var(--border);
            line-height: 1.4;
        }

        .compare-table tr:last-child td { border-bottom: none; }

        .compare-table .country-col {
            font-weight: 700;
            color: var(--text-primary);
        }

        .co2-low  { color: var(--accent); font-weight: 700; font-family: var(--font-mono); }
        .co2-mid  { color: var(--accent-yellow); font-weight: 700; font-family: var(--font-mono); }
        .co2-high { color: var(--accent-orange); font-weight: 700; font-family: var(--font-mono); }

        .energy-takeaways {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 1rem);
        }

        .takeaway-item {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.5vw, 1rem);
        }

        .takeaway-item h4 {
            font-size: var(--body-size);
            font-weight: 700;
            color: var(--text-primary);
            margin-bottom: 0.3em;
        }

        .takeaway-item p {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.45;
        }

        /* ==========================================
           SLIDE 9: KEY TAKEAWAYS
           ========================================== */
        .takeaways-layout {
            display: grid;
            grid-template-rows: auto 1fr;
            gap: clamp(0.75rem, 2vh, 1.5rem);
            height: 100%;
            padding: var(--slide-padding);
            padding-top: calc(var(--slide-padding) + 2.5rem);
            position: relative;
            z-index: 2;
        }

        .takeaways-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.75rem, 2vw, 1.5rem);
            overflow: hidden;
        }

        .key-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.875rem, 2vw, 1.5rem);
            display: flex;
            flex-direction: column;
            gap: clamp(0.35rem, 1vh, 0.6rem);
        }

        .key-card-num {
            font-family: var(--font-mono);
            font-size: clamp(0.6rem, 0.9vw, 0.75rem);
            color: var(--accent);
            text-transform: uppercase;
            letter-spacing: 0.12em;
        }

        .key-card h3 {
            font-family: var(--font-display);
            font-size: clamp(0.9rem, 1.8vw, 1.25rem);
            font-weight: 700;
            color: var(--text-primary);
            line-height: 1.25;
        }

        .key-card p {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .key-card:nth-child(1) { border-top: 3px solid var(--accent-red); }
        .key-card:nth-child(2) { border-top: 3px solid var(--accent-orange); }
        .key-card:nth-child(3) { border-top: 3px solid var(--accent); }
        .key-card:nth-child(4) { border-top: 3px solid var(--accent-blue); }

        .closing-note {
            grid-column: 1 / -1;
            background: var(--accent-dim);
            border: 1px solid rgba(0, 201, 167, 0.25);
            border-radius: 8px;
            padding: clamp(0.6rem, 1.5vw, 1rem);
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .closing-note strong { color: var(--accent); }

    </style>
</head>
<body>

    <!-- Progress bar -->
